export function parseCsvLine(s) {
  const out = [];
  let cur = "", inQuotes = false;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (inQuotes) {
      if (c === "\"") {
        if (s[i + 1] === "\"") { cur += "\""; i++; } else inQuotes = false;
      } else cur += c;
    } else if (c === "\"") inQuotes = true;
    else if (c === ",") { out.push(cur); cur = ""; }
    else cur += c;
  }
  out.push(cur);
  return out;
}

