  assert.deepEqual(parseCsvLine('a,"b,c",d,'), ["a", "b,c", "d", ""]);
});
test("escaped quotes", () => {
  assert.deepEqual(parseCsvLine('"x""y",z'), ['x"y', "z"]);
});
